public class Solution {
    // CONTRACT: index of the LAST occurrence of key, or -1.
    public static int lastIndexOf(int[] arr, int key) {
        // BUG: always reports the FIRST occurrence (or -1).
        int at = -1;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == key && at == -1) {
                at = i;
            }
        }
        return at;
    }
}
